package org.brightstats.data;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.data.DataPreparation.*;
import org.brightstats.data.DataTransforms.*;
public final class DataTransformsChecks {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void close(double a,double b){require(Math.abs(a-b)<1e-12*Math.max(1,Math.abs(b)),"Numeric transform mismatch");}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid transform accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{var raw=new Raw(List.of("X","W","Group"),List.of(List.of("1","4","A"),List.of("","9","B"),List.of("3","16","A"),List.of("5","25","")));var settings=new Settings(',',Decimal.DOT,"NA",Missing.MEAN_REPLACEMENT);var definitions=List.of(new Column("X",Kind.NUMERIC),new Column("W",Kind.NUMERIC),new Column("Group",Kind.TEXT));var prepared=DataPreparation.prepare(raw,settings,definitions);var history=ImportHistory.capture("Transform checks",raw,settings,definitions);var deletedSettings=new Settings(',',Decimal.DOT,"NA",Missing.REMOVE_ROWS);var deleted=DataPreparation.prepare(raw,deletedSettings,definitions);var recovered=MissingInput.originalAll(ImportHistory.capture("Deleted source",raw,deletedSettings,definitions),deleted.columns(),deleted.values());require(deleted.values().length==2&&recovered.length==4,"Original removed cases were not recovered");require(Double.isNaN(recovered[1][0])&&recovered[3][1]==25,"Original missing cells/source rows changed");JsonObject metadata=new JsonObject();metadata.addProperty("sourceType","EXCEL");history.add("formatSource",metadata);String original=history.toString();var json=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonArray cases=new JsonArray();
        List<Specification> specs=List.of(new Specification(Operation.DUMMY,List.of("Group"),List.of("Group_B","Group_missing"),List.of("A","B","[missing]"),"A",Map.of(),null,null,null,null,"[missing]"),new Specification(Operation.RECODE,List.of("Group"),List.of("GroupCode"),List.of(),"",Map.of("A",10.0,"B",20.0,"[missing]",0.0),null,null,null,null,"[missing]"),new Specification(Operation.AFFINE,List.of("X"),List.of("X_affine"),List.of(),"",Map.of(),2.0,3.0,null,null,null),new Specification(Operation.LOG,List.of("W"),List.of("log_W"),List.of(),"",Map.of(),null,null,null,null,null),new Specification(Operation.SQRT,List.of("W"),List.of("sqrt_W"),List.of(),"",Map.of(),null,null,null,null,null),new Specification(Operation.SQUARE,List.of("X"),List.of("X_square"),List.of(),"",Map.of(),null,null,null,null,null),new Specification(Operation.PRODUCT,List.of("X","W"),List.of("XW"),List.of(),"",Map.of(),null,null,null,null,null),new Specification(Operation.SUM,List.of("X","W"),List.of("X_plus_W"),List.of(),"",Map.of(),null,null,null,null,null),new Specification(Operation.MEAN,List.of("X","W"),List.of("X_W_mean"),List.of(),"",Map.of(),null,null,null,null,null),new Specification(Operation.REVERSE,List.of("W"),List.of("W_reverse"),List.of(),"",Map.of(),null,null,0.0,30.0,null));
        for(var spec:specs){var result=DataTransforms.append(history,prepared.columns(),prepared.values(),spec);require(history.toString().equals(original),"Original history mutated");require(result.prepared().sourceRows().equals(prepared.sourceRows()),"Source rows changed");require(result.history().getAsJsonObject("formatSource").equals(metadata),"Original format metadata dropped");ImportHistory.verify(result.history(),result.prepared().columns(),result.prepared().values());double[][] originalCells=PredictionInput.original(result.history(),result.prepared().columns(),result.prepared().values());if(!List.of(Operation.DUMMY,Operation.RECODE,Operation.LOG,Operation.SQRT,Operation.REVERSE).contains(spec.operation()))require(Double.isNaN(originalCells[1][2]),"Derived missing value lost before cross-validation");JsonObject item=new JsonObject();item.add("specification",json.toJsonTree(spec));item.add("history",result.history());item.add("prepared",json.toJsonTree(result.prepared()));item.add("originalNumeric",json.toJsonTree(originalCells));cases.add(item);}
        var square=DataTransforms.append(history,prepared.columns(),prepared.values(),specs.get(5));close(square.prepared().values()[1][2],35.0/3);require(square.prepared().values()[1][2]!=Math.pow(prepared.values()[1][0],2),"Transform must precede imputation");var composite=new Specification(Operation.LOG,List.of("X_square"),List.of("log_X_square"),List.of(),"",Map.of(),null,null,null,null,null);var twice=DataTransforms.append(square.history(),square.prepared().columns(),square.prepared().values(),composite);ImportHistory.verify(twice.history(),twice.prepared().columns(),twice.prepared().values());require(twice.history().getAsJsonArray("transformations").size()==2,"Chained history lost");close(twice.prepared().values()[1][3],(StrictMath.log(1)+StrictMath.log(9)+StrictMath.log(25))/3);var tampered=square.history();tampered.getAsJsonObject("raw").getAsJsonArray("rows").get(0).getAsJsonArray().set(3,new JsonPrimitive("999"));reject(()->ImportHistory.read(tampered));
        reject(()->DataTransforms.append(history,prepared.columns(),prepared.values(),new Specification(Operation.RECODE,List.of("Group"),List.of("Code"),List.of(),"",Map.of("A",1.0),null,null,null,null,null)));reject(()->DataTransforms.append(history,prepared.columns(),prepared.values(),new Specification(Operation.SQUARE,List.of("X"),List.of("W"),List.of(),"",Map.of(),null,null,null,null,null)));reject(()->DataTransforms.append(history,prepared.columns(),prepared.values(),new Specification(Operation.REVERSE,List.of("W"),List.of("Reverse"),List.of(),"",Map.of(),null,null,0.0,10.0,null)));reject(()->new Specification(Operation.PRODUCT,List.of("X"),List.of("Product"),List.of(),"",Map.of(),null,null,null,null,null));
        var commaRaw=new Raw(List.of("X"),List.of(List.of("1,5"),List.of(""),List.of("3,5")));var commaSettings=new Settings(';',Decimal.COMMA,"",Missing.MEAN_REPLACEMENT);var commaDefinitions=List.of(new Column("X",Kind.NUMERIC));var commaPrepared=DataPreparation.prepare(commaRaw,commaSettings,commaDefinitions);var comma=DataTransforms.append(ImportHistory.capture("Comma",commaRaw,commaSettings,commaDefinitions),commaPrepared.columns(),commaPrepared.values(),new Specification(Operation.AFFINE,List.of("X"),List.of("Twice"),List.of(),"",Map.of(),2.0,0.0,null,null,null));close(comma.prepared().values()[1][1],5);require(comma.raw().rows().getFirst().get(1).equals("3,0"),"Derived locale encoding changed");ImportHistory.verify(comma.history(),comma.prepared().columns(),comma.prepared().values());
        var plain=DataTransforms.append(null,List.of("X","Y"),new double[][]{{1,2},{3,4}},specs.get(5));close(plain.prepared().values()[1][2],9);ImportHistory.verify(plain.history(),plain.prepared().columns(),plain.prepared().values());Thread.currentThread().interrupt();try{DataTransforms.append(history,prepared.columns(),prepared.values(),specs.get(5));throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),json.toJson(cases));Files.writeString(output.resolve("chained-history.json"),json.toJson(twice.history()));System.out.println("Data transform checks: "+checks);}
}
